def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    durable_pressure = 0.0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) >= 3 and opp.get('budget', 0) >= DAILY_SALARY * 4:
                    if bid > durable_pressure:
                        durable_pressure = float(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    slots = supply / float(WATER_REQ)
    scarce = slots < (len(alive) + 1)
    very_scarce = slots < max(1.5, (len(alive) + 1) * 0.7)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure = max(highest_prev, durable_pressure)

    critical = hp <= 2 or no_water_days >= 2
    strained = hp <= 4 or no_water_days >= 1

    if critical:
        if pressure > 0:
            bid = min(budget, max(DAILY_SALARY * 0.95, pressure + 2.5))
        else:
            bid = min(budget, DAILY_SALARY * 0.9)
        return max(0.0, bid)

    if very_scarce:
        if pressure >= 90:
            bid = DAILY_SALARY * 0.82 if hp >= 5 else DAILY_SALARY * 0.96
        elif pressure > 0:
            bid = min(DAILY_SALARY * 0.9, max(DAILY_SALARY * 0.62, pressure + 1.5))
        else:
            bid = DAILY_SALARY * 0.68
    elif scarce:
        if pressure >= 90:
            bid = DAILY_SALARY * 0.45 if hp >= 6 else DAILY_SALARY * 0.78
        elif pressure > 0:
            bid = max(DAILY_SALARY * 0.45, min(DAILY_SALARY * 0.72, pressure * 0.72))
        else:
            bid = DAILY_SALARY * 0.5
    else:
        if strained:
            bid = DAILY_SALARY * 0.52
        else:
            bid = DAILY_SALARY * 0.34

    if day >= 8 and hp >= 5 and budget > DAILY_SALARY * 6:
        bid *= 0.9

    if budget < DAILY_SALARY * 2 and not critical:
        bid = min(bid, DAILY_SALARY * 0.55)

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        bid = DAILY_SALARY * 0.6
    else:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_bid * 1.05

    if my_status['hp'] < 5:
        bid = max(bid, DAILY_SALARY * 0.85)

    return float(min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Find Alex's previous bid if available
    alex_trace = opponents_status.get('Alex', {}).get('previous_trace', {})
    alex_prev_bid = None
    if alex_trace and 'bid' in alex_trace:
        alex_prev_bid = alex_trace['bid']

    # Determine base need-based bid
    needed_ratio = WATER_REQ / supply if supply > 0 else 1.0
    base_bid = needed_ratio * DAILY_SALARY * 0.8  # conservative

    # Adjust based on hunger
    if hp <= 2 or no_water_days >= 2:
        # Desperate: need to win
        if alex_prev_bid:
            target = alex_prev_bid + 1.5
        else:
            target = DAILY_SALARY * 0.9
        bid = max(target, base_bid)
    elif hp <= 5:
        # Mild need: match or slightly beat Alex if he was high
        if alex_prev_bid and alex_prev_bid > base_bid:
            bid = alex_prev_bid + 1.0
        else:
            bid = base_bid
    else:
        # Healthy: bid low to save
        if alex_prev_bid and alex_prev_bid < DAILY_SALARY * 0.4:
            bid = alex_prev_bid - 0.5
        else:
            bid = DAILY_SALARY * 0.2

    # Ensure we don't exceed budget and not negative
    bid = min(budget, max(0, bid))
    # Smooth for supply extremes
    if supply < 18:
        bid = min(budget, bid * 1.2)
    return round(bid, 2)
